//! `Decoder::output_params` / `output_params_generation` (oxideav-core
//! 0.1.42): the decoder states the shape of the frames it emits once,
//! at the stream level, instead of in every frame.
//!
//! Gates, on black-box libx265 fixtures (`tests/fixtures/output_params/`,
//! regenerated by `gen.sh` there, which also records what `ffprobe`
//! reports in `expected.txt`):
//!
//! * the answer is available from the `hvcC` record right after
//!   construction, before any packet, and equals the answer after the
//!   first frame;
//! * every emitted frame's planes have exactly the geometry the answer
//!   states (§7.4.3.2.1 conformance-cropped size, Table 6-1 chroma
//!   subsampling, bytes per sample of the bit depth), and the answer
//!   matches `ffprobe` (width, height, pix_fmt, colour primaries /
//!   transfer / matrix and range, r_frame_rate);
//! * a stream whose second coded video sequence changes size and bit
//!   depth bumps the generation exactly once, at the first frame of the
//!   new shape;
//! * the answers and generations after every frame are identical with
//!   1 and 8 worker threads.

use oxideav_core::{
    CodecId, CodecParameters, ColorRange, ColorSignal, Decoder, ExecutionContext, Frame,
    OutputParamsWatch, Packet, PixelFormat, Rational, TimeBase, VideoFrame,
};
use oxideav_h265::make_decoder;

const DIR: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/output_params");

fn fixture(name: &str) -> Vec<u8> {
    std::fs::read(format!("{DIR}/{name}")).expect("fixture")
}

/// Split an Annex B byte stream into NAL unit payloads (no start code).
fn nal_payloads(data: &[u8]) -> Vec<&[u8]> {
    let mut starts = Vec::new();
    let mut i = 0usize;
    while i + 3 <= data.len() {
        if data[i] == 0 && data[i + 1] == 0 && data[i + 2] == 1 {
            starts.push(i + 3);
            i += 3;
        } else {
            i += 1;
        }
    }
    (0..starts.len())
        .map(|k| {
            let mut end = starts.get(k + 1).map(|&s| s - 3).unwrap_or(data.len());
            while end > starts[k] && data[end - 1] == 0 {
                end -= 1;
            }
            &data[starts[k]..end]
        })
        .collect()
}

fn nal_type(n: &[u8]) -> u8 {
    (n[0] >> 1) & 0x3f
}

/// One expected.txt row: what ffprobe reported.
struct Probe {
    width: u32,
    height: u32,
    pix_fmt: String,
    range: String,
    space: String,
    transfer: String,
    primaries: String,
    r_frame_rate: (i64, i64),
    frames: usize,
}

fn probe(name: &str) -> Probe {
    let text = std::fs::read_to_string(format!("{DIR}/expected.txt")).expect("expected.txt");
    let line = text
        .lines()
        .find(|l| l.split_whitespace().next() == Some(name))
        .unwrap_or_else(|| panic!("{name} not in expected.txt"));
    let get = |k: &str| {
        line.split_whitespace()
            .find_map(|kv| kv.strip_prefix(&format!("{k}=")).map(str::to_owned))
            .unwrap_or_else(|| panic!("{name}: no {k}"))
    };
    let rate = get("r_frame_rate");
    let (n, d) = rate.split_once('/').expect("rate");
    Probe {
        width: get("width").parse().unwrap(),
        height: get("height").parse().unwrap(),
        pix_fmt: get("pix_fmt"),
        range: get("color_range"),
        space: get("color_space"),
        transfer: get("color_transfer"),
        primaries: get("color_primaries"),
        r_frame_rate: (n.parse().unwrap(), d.parse().unwrap()),
        frames: get("nb_read_frames").parse().unwrap(),
    }
}

fn ffprobe_pix_fmt(s: &str) -> PixelFormat {
    match s {
        "yuv420p" => PixelFormat::Yuv420P,
        "yuv422p" => PixelFormat::Yuv422P,
        "yuv444p" => PixelFormat::Yuv444P,
        "yuv420p10le" => PixelFormat::Yuv420P10Le,
        "yuv422p10le" => PixelFormat::Yuv422P10Le,
        "yuv444p10le" => PixelFormat::Yuv444P10Le,
        "yuv444p12le" => PixelFormat::Yuv444P12Le,
        "gray" => PixelFormat::Gray8,
        "gray10le" => PixelFormat::Gray10Le,
        other => panic!("unmapped ffprobe pix_fmt {other}"),
    }
}

/// ffprobe colour names → H.273 code points (2 = unspecified).
fn h273(s: &str) -> u8 {
    match s {
        "unknown" => 2,
        "bt709" => 1,
        "bt470bg" => 5,
        "smpte170m" => 6,
        "bt2020" | "bt2020nc" => 9,
        "smpte2084" => 16,
        other => panic!("unmapped ffprobe colour name {other}"),
    }
}

fn reduce(n: i64, d: i64) -> Rational {
    let (mut a, mut b) = (n, d);
    while b != 0 {
        (a, b) = (b, a % b);
    }
    Rational::new(n / a, d / a)
}

/// Assert `p` is what ffprobe reported for the fixture.
fn assert_matches_probe(p: &CodecParameters, pr: &Probe, tag: &str) {
    assert_eq!(p.width, Some(pr.width), "{tag}: width");
    assert_eq!(p.height, Some(pr.height), "{tag}: height");
    assert_eq!(
        p.pixel_format,
        Some(ffprobe_pix_fmt(&pr.pix_fmt)),
        "{tag}: pixel format"
    );
    let range = match pr.range.as_str() {
        "tv" => ColorRange::Limited,
        "pc" => ColorRange::Full,
        _ => ColorRange::Unspecified,
    };
    let mut want = ColorSignal::from_code_points(
        h273(&pr.primaries),
        h273(&pr.transfer),
        h273(&pr.space),
        range == ColorRange::Full,
    );
    want.range = range;
    assert_eq!(p.color_signal, want, "{tag}: colour signal");
    let (n, d) = pr.r_frame_rate;
    assert_eq!(p.frame_rate, Some(reduce(n, d)), "{tag}: frame rate");
}

/// Bytes per sample row / rows of each plane `pf` stores at `w` x `h`.
fn plane_geometry(pf: PixelFormat, w: usize, h: usize) -> Vec<(usize, usize)> {
    use PixelFormat::*;
    let (bps, sub, planes) = match pf {
        Gray8 => (1, (1, 1), 1),
        Gray10Le | Gray12Le => (2, (1, 1), 1),
        Yuv420P => (1, (2, 2), 3),
        Yuv422P => (1, (2, 1), 3),
        Yuv444P => (1, (1, 1), 3),
        Yuv420P10Le | Yuv420P12Le => (2, (2, 2), 3),
        Yuv422P10Le | Yuv422P12Le => (2, (2, 1), 3),
        Yuv444P10Le | Yuv444P12Le => (2, (1, 1), 3),
        other => panic!("unexpected layout {other:?}"),
    };
    let mut g = vec![(w * bps, h)];
    for _ in 1..planes {
        g.push((w.div_ceil(sub.0) * bps, h.div_ceil(sub.1)));
    }
    g
}

fn assert_frame_matches(vf: &VideoFrame, p: &CodecParameters, tag: &str) {
    let geom = plane_geometry(
        p.pixel_format.expect("pixel format"),
        p.width.unwrap() as usize,
        p.height.unwrap() as usize,
    );
    let got: Vec<(usize, usize)> = vf
        .image_planes()
        .iter()
        .map(|pl| (pl.stride, pl.data.len() / pl.stride.max(1)))
        .collect();
    assert_eq!(got, geom, "{tag}: plane geometry vs output_params");
}

/// The decoder-owned fields of an `output_params` answer.
#[derive(Clone, Debug, PartialEq)]
struct Desc {
    width: Option<u32>,
    height: Option<u32>,
    pixel_format: Option<PixelFormat>,
    frame_rate: Option<Rational>,
    color_signal: ColorSignal,
}

impl Desc {
    fn of(p: &CodecParameters) -> Self {
        Self {
            width: p.width,
            height: p.height,
            pixel_format: p.pixel_format,
            frame_rate: p.frame_rate,
            color_signal: p.color_signal,
        }
    }
}

/// `(output_params, generation)` after each frame.
type Trace = Vec<(CodecParameters, u64)>;

fn descs(t: &Trace) -> Vec<(Desc, u64)> {
    t.iter().map(|(p, g)| (Desc::of(p), *g)).collect()
}

fn drain(dec: &mut dyn Decoder, trace: &mut Trace, tag: &str) {
    while let Ok(f) = dec.receive_frame() {
        let Frame::Video(vf) = f else {
            panic!("{tag}: non-video frame")
        };
        let p = dec.output_params().expect("answer after a frame");
        assert_frame_matches(&vf, &p, tag);
        assert_eq!(
            dec.output_pixel_format(),
            p.pixel_format,
            "{tag}: forwarded"
        );
        trace.push((p, dec.output_params_generation()));
    }
}

/// Decode an Annex B stream one NAL per packet, draining after each.
fn decode_streamed(bytes: &[u8], threads: usize, tag: &str) -> Trace {
    let mut dec = make_decoder(&CodecParameters::video(CodecId::new("h265"))).expect("decoder");
    dec.set_execution_context(&ExecutionContext::with_threads(threads));
    let mut trace = Vec::new();
    for (i, nal) in nal_payloads(bytes).into_iter().enumerate() {
        let mut d = vec![0, 0, 0, 1];
        d.extend_from_slice(nal);
        let pkt = Packet::new(0, TimeBase::new(1, 25), d).with_pts(i as i64);
        dec.send_packet(&pkt).expect("send");
        drain(&mut *dec, &mut trace, tag);
    }
    dec.flush().expect("flush");
    drain(&mut *dec, &mut trace, tag);
    trace
}

/// `hvcC` (ISO/IEC 14496-15 §8.3.3.1.2) carrying the stream's VPS /
/// SPS / PPS, and the other NAL units as 4-byte length-prefixed
/// packets, one per NAL.
fn to_hvcc(bytes: &[u8]) -> (Vec<u8>, Vec<Vec<u8>>) {
    let nals = nal_payloads(bytes);
    let mut rec = vec![1u8];
    rec.extend_from_slice(&[0; 11]); // profile / tier / compat / constraints
    rec.push(0); // level
    rec.extend_from_slice(&[0xf0, 0x00, 0xfc, 0xfc, 0xf8, 0xf8, 0, 0]);
    rec.push(0x0f); // lengthSizeMinusOne = 3
    let mut arrays = Vec::new();
    for t in [32u8, 33, 34] {
        let units: Vec<&&[u8]> = nals.iter().filter(|n| nal_type(n) == t).take(1).collect();
        arrays.push(0x80 | t);
        arrays.extend_from_slice(&(units.len() as u16).to_be_bytes());
        for u in units {
            arrays.extend_from_slice(&(u.len() as u16).to_be_bytes());
            arrays.extend_from_slice(u);
        }
    }
    rec.push(3);
    rec.extend_from_slice(&arrays);
    let packets = nals
        .iter()
        .filter(|n| !matches!(nal_type(n), 32..=34))
        .map(|n| {
            let mut p = (n.len() as u32).to_be_bytes().to_vec();
            p.extend_from_slice(n);
            p
        })
        .collect();
    (rec, packets)
}

const LAYOUT_FIXTURES: &[&str] = &[
    "yuv420p_70x46_25.hevc",
    "yuv422p_64x48_30.hevc",
    "yuv444p_48x32_24.hevc",
    "gray_64x48_25.hevc",
    "yuv420p10_64x48_50.hevc",
    "yuv422p10_48x32_25.hevc",
    "yuv444p12_32x32_25.hevc",
    "gray10_32x32_25.hevc",
];

#[test]
fn answer_from_hvcc_before_the_first_frame_matches_ffprobe_and_frames() {
    for &name in LAYOUT_FIXTURES {
        let pr = probe(name);
        let (hvcc, packets) = to_hvcc(&fixture(name));
        let mut params = CodecParameters::video(CodecId::new("h265"));
        params.extradata = hvcc;
        let mut dec = make_decoder(&params).expect("make_decoder");
        let before = dec.output_params().expect("answer from hvcC");
        assert_matches_probe(&before, &pr, &format!("{name} (hvcC)"));
        assert_eq!(dec.output_params_generation(), 0);

        let mut stream = params.clone();
        let watch = OutputParamsWatch::new();
        assert!(watch.prime(&*dec, &mut stream), "{name}: prime fills");
        assert_eq!(stream.width, Some(pr.width));
        assert_eq!(stream.extradata, params.extradata, "container field kept");

        let mut trace = Vec::new();
        for (i, p) in packets.into_iter().enumerate() {
            let pkt = Packet::new(0, TimeBase::new(1, 25), p).with_pts(i as i64);
            dec.send_packet(&pkt).expect("send");
            drain(&mut *dec, &mut trace, name);
        }
        dec.flush().expect("flush");
        drain(&mut *dec, &mut trace, name);
        assert_eq!(trace.len(), pr.frames, "{name}: frame count vs ffprobe");
        for (p, generation) in &trace {
            assert_eq!(Desc::of(p), Desc::of(&before), "{name}: stable answer");
            assert_eq!(*generation, 0, "{name}: no change, no bump");
        }
    }
}

#[test]
fn annex_b_answers_match_ffprobe_at_1_and_8_threads() {
    for &name in LAYOUT_FIXTURES {
        let pr = probe(name);
        let bytes = fixture(name);
        let t1 = decode_streamed(&bytes, 1, name);
        let t8 = decode_streamed(&bytes, 8, name);
        assert_eq!(t1.len(), pr.frames, "{name}: frame count");
        for (p, generation) in &t1 {
            assert_matches_probe(p, &pr, name);
            assert_eq!(*generation, 0);
        }
        assert_eq!(descs(&t1), descs(&t8), "{name}: 1 vs 8 threads");
    }
}

#[test]
fn generation_bumps_exactly_at_the_first_frame_of_the_new_shape() {
    let bytes = fixture("change_64x48_8bit_then_48x32_10bit.hevc");
    let mut traces = Vec::new();
    for threads in [1, 8] {
        let trace = decode_streamed(&bytes, threads, "change");
        let shapes: Vec<(u32, u32, PixelFormat, u64)> = trace
            .iter()
            .map(|(p, g)| {
                (
                    p.width.unwrap(),
                    p.height.unwrap(),
                    p.pixel_format.unwrap(),
                    *g,
                )
            })
            .collect();
        let mut want = vec![(64, 48, PixelFormat::Yuv420P, 0); 5];
        want.extend(vec![(48, 32, PixelFormat::Yuv420P10Le, 1); 5]);
        assert_eq!(shapes, want, "{threads} thread(s)");
        traces.push(descs(&trace));
    }
    assert_eq!(traces[0], traces[1], "1 vs 8 threads");

    // Whole stream queued before the first receive: the new SPS has been
    // parsed long before the old-shape frames come out, and the answer
    // still follows the frames.
    let mut dec = make_decoder(&CodecParameters::video(CodecId::new("h265"))).expect("decoder");
    dec.send_packet(&Packet::new(0, TimeBase::new(1, 25), bytes.clone()).with_pts(0))
        .expect("send");
    dec.flush().expect("flush");
    let mut stream = CodecParameters::video(CodecId::new("h265"));
    let mut watch = OutputParamsWatch::new();
    watch.prime(&*dec, &mut stream);
    assert_eq!((stream.width, stream.height), (Some(64), Some(48)));
    let mut changes = Vec::new();
    let mut n = 0;
    while let Ok(Frame::Video(vf)) = dec.receive_frame() {
        if watch.observe(&*dec, &mut stream) {
            changes.push(n);
        }
        assert_frame_matches(&vf, &stream, "watched stream");
        n += 1;
    }
    assert_eq!(n, 10);
    assert_eq!(changes, vec![5], "one change, at frame 5");
}

/// Multi-layer output (Annex F/G/H, the crate's own layered fixtures):
/// the views of an MV-HEVC stream share one description — the
/// enhancement layer's SPS carries no VUI and takes the base layer's
/// timing / colour — so the generation never moves; a spatially
/// scalable stream that outputs both layers re-states the size at each
/// frame of the other layer.
#[test]
fn multi_layer_output_descriptions() {
    let read = |n: &str| {
        std::fs::read(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixture_bytes/").to_owned() + n)
            .expect("fixture")
    };
    let whole = |bytes: &[u8], threads: usize| -> Vec<(Desc, u64)> {
        let mut dec = make_decoder(&CodecParameters::video(CodecId::new("h265"))).expect("decoder");
        dec.set_execution_context(&ExecutionContext::with_threads(threads));
        dec.send_packet(&Packet::new(0, TimeBase::new(1, 25), bytes.to_vec()).with_pts(0))
            .expect("send");
        dec.flush().expect("flush");
        let mut trace = Vec::new();
        drain(&mut *dec, &mut trace, "multi-layer");
        descs(&trace)
    };
    let mv = read("r462-mvhevc-3au.hevc");
    let t = whole(&mv, 1);
    assert_eq!(t.len(), 6, "3 access units x 2 views");
    assert!(t.iter().all(|d| d == &t[0]), "one description: {t:?}");
    assert_eq!(t[0].1, 0);
    assert_eq!(t, whole(&mv, 8), "1 vs 8 threads");

    let shvc = read("r462-shvc-2x.hevc");
    let t = whole(&shvc, 1);
    let sizes: Vec<(Option<u32>, u64)> = t.iter().map(|(d, g)| (d.width, *g)).collect();
    assert_eq!(sizes, vec![(Some(32), 0), (Some(64), 1)]);
    assert_eq!(t, whole(&shvc, 8), "1 vs 8 threads");
}

/// `reset` (a seek) drops everything decoded before it, keeps the
/// `hvcC` parameter sets, and decodes from the next IRAP picture
/// exactly as a straight decode does; the generation does not move at
/// the reset, only at the first returned frame of a different shape.
#[test]
fn reset_seeks_to_the_next_irap() {
    fn video(f: Frame) -> VideoFrame {
        match f {
            Frame::Video(v) => v,
            _ => panic!("non-video frame"),
        }
    }
    let name = "yuv420p10_64x48_50.hevc";
    let (hvcc, packets) = to_hvcc(&fixture(name));
    let mut params = CodecParameters::video(CodecId::new("h265"));
    params.extradata = hvcc;
    let decode = |packets: &[Vec<u8>], reset_after: Option<usize>| -> Vec<Vec<u8>> {
        let mut dec = make_decoder(&params).expect("make_decoder");
        let mut frames = Vec::new();
        if let Some(n) = reset_after {
            for p in &packets[..n] {
                dec.send_packet(&Packet::new(0, TimeBase::new(1, 25), p.clone()))
                    .expect("send");
                let _ = dec.receive_frame();
            }
            dec.reset().expect("reset");
        }
        let start = reset_after.map_or(0, |_| {
            // The second IRAP (nal_unit_type 16..=21) of the stream.
            packets
                .iter()
                .enumerate()
                .filter(|(_, p)| (16..=21).contains(&nal_type(&p[4..])))
                .nth(1)
                .expect("second IRAP")
                .0
        });
        for p in &packets[start..] {
            dec.send_packet(&Packet::new(0, TimeBase::new(1, 25), p.clone()))
                .expect("send");
            while let Ok(f) = dec.receive_frame() {
                frames.push(video(f).planes.concat_data());
            }
        }
        dec.flush().expect("flush");
        while let Ok(f) = dec.receive_frame() {
            frames.push(video(f).planes.concat_data());
        }
        assert_eq!(dec.output_params_generation(), 0);
        frames
    };
    let straight = decode(&packets, None);
    let seeked = decode(&packets, Some(6));
    assert_eq!(straight.len(), 10);
    // The second GOP opens with a CRA picture whose RASL picture is
    // output ahead of it (straight[4]); after the seek the RASL picture
    // is skipped (§8.1.3 — its reference precedes the CRA picture) and
    // the rest is the straight decode's tail.
    assert_eq!(seeked.len(), 5, "the CRA picture and what follows it");
    assert_eq!(
        seeked,
        straight[5..],
        "same pictures as the straight decode"
    );

    // Back to a differently shaped segment: the bump comes with the
    // first frame returned after the seek, not with the reset.
    let bytes = fixture("change_64x48_8bit_then_48x32_10bit.hevc");
    let nals = nal_payloads(&bytes);
    let annexb = |n: &[u8]| {
        let mut d = vec![0, 0, 0, 1];
        d.extend_from_slice(n);
        Packet::new(0, TimeBase::new(1, 25), d)
    };
    let mut dec = make_decoder(&CodecParameters::video(CodecId::new("h265"))).expect("decoder");
    for n in &nals {
        dec.send_packet(&annexb(n)).expect("send");
    }
    dec.flush().expect("flush");
    while dec.receive_frame().is_ok() {}
    assert_eq!(dec.output_params().and_then(|p| p.width), Some(48));
    let generation = dec.output_params_generation();
    dec.reset().expect("reset");
    assert_eq!(
        dec.output_params_generation(),
        generation,
        "no bump at reset"
    );
    for n in &nals {
        dec.send_packet(&annexb(n)).expect("send");
        if let Ok(f) = dec.receive_frame() {
            let p = dec.output_params().expect("answer");
            assert_frame_matches(&video(f), &p, "after the seek");
            assert_eq!(p.width, Some(64));
            assert_eq!(dec.output_params_generation(), generation.wrapping_add(1));
            return;
        }
    }
    panic!("no frame after the seek");
}

trait ConcatData {
    fn concat_data(&self) -> Vec<u8>;
}

impl ConcatData for Vec<oxideav_core::VideoPlane> {
    fn concat_data(&self) -> Vec<u8> {
        self.iter().flat_map(|p| p.data.iter().copied()).collect()
    }
}
